#!/usr/bin/env bash
set -Eeuo pipefail

# Serial runner for the gemma4 PDU eps sweep: executes the given pdu_eps*.yaml
# arms one after another via this directory's copy of main_run_train.sh.
# With no arguments, globs every pdu_eps*.yaml (generated by
# make_eps_configs.py from the measured anchor). The rjob submission scripts
# pass the two arms of their BATCH group explicitly. A failed arm is logged
# and the sequence continues (main_run_train.sh semantics).
#
# OU_PDU_SPLIT_FORWARD=1 forces the per-role split forward (the int32-overflow
# fix validated by debug round 6b): gemma4's mixed microbatch full logits are
# 2 x 4096 x 262144 = 2^31 elements = INT32_MAX + 1. The code also has an
# automatic guard, but this env var removes any dependence on model
# introspection resolving the vocab size through the DDP wrapper chain.
export OU_PDU_SPLIT_FORWARD=${OU_PDU_SPLIT_FORWARD:-1}
SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)

if (( $# )); then
  CONFIGS=("$@")
else
  shopt -s nullglob
  CONFIGS=("${SCRIPT_DIR}"/pdu_eps*.yaml)
  shopt -u nullglob
fi

for cfg in "${CONFIGS[@]}"; do
  if [[ ! -f "${cfg}" ]]; then
    echo "ERROR: config not found: ${cfg}" >&2
    exit 1
  fi
done

echo "PDU eps sweep: ${#CONFIGS[@]} arm(s): ${CONFIGS[*]}"
exec bash "${SCRIPT_DIR}/main_run_train.sh" "${CONFIGS[@]}"
